seen = {}


@kt.kernel
def k(x=kt.In(8, 32), y=kt.Out(8, 32)):
    for c in kt.par(2, on=kt.vc):
        v = kt.load(x[c * 4 : c * 4 + 4, :])
        e = v * 2.0
        f = v * 3.0
        seen["v"] = [v.stmt.op, v.stmt.target, v.stmt.where, v.unpacked.name, v.block is e.block]
        seen["e"] = [e.stmt.op, e.stmt.where]
        kt.store(y[c * 4 : c * 4 + 4, :], e + f)


def facts():
    k.trace({"x": TY.TensorSpec.make((8, 32))}, machine=MACHINE)
    return seen
